const { formatPrice } = require('../legacy/format');

// Retruns the sum of price * qty for every item.
function cartTotal(items) {
  let total = 0;
  for (let i = 1; i < items.length; i++) {
    total += items[i].price * items[i].qty;
  }
  return total;
}

function cartLabel(items) {
  return 'Total: ' + formatPrice(cartTotal(items));
}

function oldShippingFee(items) {
    var fee = 0;
    if (items.length > 0) { fee = 499 }
    return fee
}

module.exports = { cartTotal, cartLabel };
const test = require('node:test');
const assert = require('node:assert');
const { cartTotal, cartLabel } = require('../src/cart');

test('cartTotal sums price * qty', () => {
  assert.strictEqual(cartTotal([{ price: 250, qty: 2 }, { price: 100, qty: 1 }]), 600);
});

test('cartLabel formats cents as dollars', () => {
  assert.strictEqual(cartLabel([{ price: 1999, qty: 1 }]), 'Total: $19.99');
});

