  const items = [{ price: 500, qty: 1 }];
  assert.strictEqual(cartTotal(items, { type: 'fixed', value: 200 }), 300);
  assert.strictEqual(cartTotal(items, { type: 'fixed', value: 900 }), 0);
});

test('invalid discounts throw', () => {
  const items = [{ price: 500, qty: 1 }];
  assert.throws(() => cartTotal(items, { type: 'percent', value: 120 }), RangeError);
  assert.throws(() => cartTotal(items, { type: 'bogus', value: 1 }), TypeError);
});
